import{_ as s,o as n,a as t,b as p}from"./app.C41L12d5.js";const l="/ascendc.github.io/assets/loaddatawithsparse_l12l0b.C4nz7cI3.png",h=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C API","link":"/api/api_list"},{"text":"SIMD API","link":"/api/SIMD-API/SIMD-API"},{"text":"基础API","link":"/api/SIMD-API/basic_api/basic_api"},{"text":"矩阵计算（ISASI）","link":"/api/SIMD-API/basic_api/cube_compute_ISASI/cube_compute_ISASI"},{"text":"矩阵计算的搬入","link":"/api/SIMD-API/basic_api/cube_compute_ISASI/cube_compute_load/cube_compute_load"},{"text":"LoadDataWithSparse","link":"/api/SIMD-API/basic_api/cube_compute_ISASI/cube_compute_load/LoadDataWithSparse"}]},"headers":[],"relativePath":"api/SIMD-API/basic_api/cube_compute_ISASI/cube_compute_load/LoadDataWithSparse.md","filePath":"api/SIMD-API/basic_api/cube_compute_ISASI/cube_compute_load/LoadDataWithSparse.md","outlineHeaders":[{"level":2,"title":"产品支持情况","slug":"产品支持情况","link":"#产品支持情况"},{"level":2,"title":"功能说明","slug":"功能说明","link":"#功能说明"},{"level":2,"title":"函数原型","slug":"函数原型","link":"#函数原型"},{"level":2,"title":"参数说明","slug":"参数说明","link":"#参数说明"},{"level":2,"title":"数据类型","slug":"数据类型","link":"#数据类型"},{"level":2,"title":"返回值说明","slug":"返回值说明","link":"#返回值说明"},{"level":2,"title":"约束说明","slug":"约束说明","link":"#约束说明"},{"level":2,"title":"调用示例","slug":"调用示例","link":"#调用示例"}],"lastUpdated":1788159000000}'),e={name:"api/SIMD-API/basic_api/cube_compute_ISASI/cube_compute_load/LoadDataWithSparse.md"};function c(i,a,d,o,r,_){return n(),t("div",null,[...a[0]||(a[0]=[p('<div><article class="markdown-body"><h1>LoadDataWithSparse<span id="ZH-CN_TOPIC_0000002568950935"></span></h1><h2 id="产品支持情况">产品支持情况<span id="zh-cn_topic_0000002512171654_section796754519912"></span><a class="header-anchor" href="#产品支持情况">​</a></h2><div data-filter="950"><ul><li>Ascend 950PR/Ascend 950DT：不支持</li></ul></div><div data-filter="A3"><ul><li>Atlas A3 训练系列产品/Atlas A3 推理系列产品：支持</li></ul></div><div data-filter="910b"><ul><li>Atlas A2 训练系列产品/Atlas A2 推理系列产品：支持</li></ul></div><div data-filter="310b"><ul><li>Atlas 200I/500 A2 推理产品：不支持</li></ul></div><div data-filter="310p"><ul><li>Atlas 推理系列产品AI Core：不支持</li></ul></div><div data-filter="310p"><ul><li>Atlas 推理系列产品Vector Core：不支持</li></ul></div><div data-filter="910"><ul><li>Atlas 训练系列产品：不支持</li></ul></div><div data-filter="x90"><ul><li>Kirin X90：不支持</li></ul></div><div data-filter="9030"><ul><li>Kirin 9030：不支持</li></ul></div><h2 id="功能说明">功能说明<span id="zh-cn_topic_0000002512171654_section106841136114319"></span><a class="header-anchor" href="#功能说明">​</a></h2><p>头文件路径为：<code>&quot;basic_api/kernel_operator_mm_intf.h&quot;</code>。</p><p>用于从L1 Buffer中搬运以512字节为单位存放的稠密权重矩阵到L0B Buffer里，同时搬运以128字节为单位的索引矩阵到内置的专用buffer空间（用于后续MmadWithSparse接口进行读取）。</p><p>索引矩阵的数据类型为uint2，需要拼成uint8的数据类型，再传入接口。索引矩阵在一个uint8的地址中的排布是逆序排布的，例如：索引矩阵在地址中的排布为1 0 2 1 0 1 2 0，其中1 0 2 1（对应索引矩阵前四位1 2 0 1）为一个uint8，0 1 2 0（对应索引矩阵后四位0 2 1 0）为一个uint8。</p><p>仅支持如下数据通路的搬运：L1 Buffer-&gt;L0B Buffer。</p><p><strong>图1</strong> L1 Buffer-&gt;L0B Buffer LoadDataWithSparse示意图，LoadData2dParams参数配置startIndex = 1，repeatTimes = 5，表示需要从源操作数src中第1块数据分形开始搬运5块连续的数据分形，从源操作数idx中第1块index分形开始搬运5块连续的index分形。<span id="zh-cn_topic_0000002512171654_fig71111314164414"></span></p><p><img src="'+l+`" alt></p><h2 id="函数原型">函数原型<span id="zh-cn_topic_0000002512171654_section82039854412"></span><a class="header-anchor" href="#函数原型">​</a></h2><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="k">template</span><span class="w"> </span><span class="o">&lt;</span><span class="k">typename</span><span class="w"> </span><span class="nc">T</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="kt">int8_t</span><span class="p">,</span><span class="w"> </span><span class="k">typename</span><span class="w"> </span><span class="nc">U</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="kt">uint8_t</span><span class="p">,</span><span class="w"> </span><span class="k">typename</span><span class="w"> </span><span class="nc">Std</span><span class="o">::</span><span class="n">enable_if</span><span class="o">&lt;</span><span class="n">Std</span><span class="o">::</span><span class="n">is_same</span><span class="o">&lt;</span><span class="n">PrimT</span><span class="o">&lt;</span><span class="n">T</span><span class="o">&gt;</span><span class="p">,</span><span class="w"> </span><span class="kt">int8_t</span><span class="o">&gt;::</span><span class="n">value</span><span class="p">,</span><span class="w"> </span><span class="kt">bool</span><span class="o">&gt;::</span><span class="n">type</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="nb">true</span><span class="p">,</span><span class="w"> </span><span class="k">typename</span><span class="w"> </span><span class="nc">Std</span><span class="o">::</span><span class="n">enable_if</span><span class="o">&lt;</span><span class="n">Std</span><span class="o">::</span><span class="n">is_same</span><span class="o">&lt;</span><span class="n">PrimT</span><span class="o">&lt;</span><span class="n">U</span><span class="o">&gt;</span><span class="p">,</span><span class="w"> </span><span class="kt">uint8_t</span><span class="o">&gt;::</span><span class="n">value</span><span class="p">,</span><span class="w"> </span><span class="kt">bool</span><span class="o">&gt;::</span><span class="n">type</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="nb">true</span><span class="o">&gt;</span>
<span class="n">__aicore__</span><span class="w"> </span><span class="kr">inline</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">LoadDataWithSparse</span><span class="p">(</span><span class="k">const</span><span class="w"> </span><span class="n">LocalTensor</span><span class="o">&lt;</span><span class="n">T</span><span class="o">&gt;&amp;</span><span class="w"> </span><span class="n">dst</span><span class="p">,</span><span class="w"> </span><span class="k">const</span><span class="w"> </span><span class="n">LocalTensor</span><span class="o">&lt;</span><span class="n">T</span><span class="o">&gt;&amp;</span><span class="w"> </span><span class="n">src</span><span class="p">,</span><span class="w"> </span><span class="k">const</span><span class="w"> </span><span class="n">LocalTensor</span><span class="o">&lt;</span><span class="n">U</span><span class="o">&gt;&amp;</span><span class="w"> </span><span class="n">idx</span><span class="p">,</span><span class="w"> </span><span class="k">const</span><span class="w"> </span><span class="n">LoadData2dParams</span><span class="o">&amp;</span><span class="w"> </span><span class="n">loadDataParam</span><span class="p">)</span>
</code></pre></div><h2 id="参数说明">参数说明<span id="zh-cn_topic_0000002512171654_section16128134420472"></span><a class="header-anchor" href="#参数说明">​</a></h2><p><strong>表1</strong> 模板参数说明</p><table><thead><tr><th>参数名</th><th>描述</th></tr></thead><tbody><tr><td>T</td><td>dst、src的数据类型。</td></tr><tr><td>U</td><td>idx的数据类型。</td></tr><tr><td>Std::enable_if&lt;Std::is_same&lt;PrimT&lt;T&gt;, int8_t&gt;::value, bool&gt;::type</td><td>用于T的数据类型检查，用户无需关注。</td></tr><tr><td>Std::enable_if&lt;Std::is_same&lt;PrimT&lt;U&gt;, uint8_t&gt;::value, bool&gt;::type</td><td>用于U的数据类型检查，用户无需关注。</td></tr></tbody></table><p><strong>表2</strong> 参数说明</p><table><thead><tr><th>参数名称</th><th>输入/输出</th><th>含义</th></tr></thead><tbody><tr><td>dst</td><td>输出</td><td>目的操作数，类型为LocalTensor。<br>分形约束参考<a href="cube_compute_input_move_constraint.html">矩阵计算输入搬运约束</a>。<br>起始地址对齐约束参考<a href="cube_compute_input_move_constraint.html">对齐约束</a>。<br>支持的数据类型为int8_t。<br>Atlas A2 训练系列产品/Atlas A2 推理系列产品，支持的物理存储位置为L0B Buffer(TPosition: B2)。<br>Atlas A3 训练系列产品/Atlas A3 推理系列产品，支持的物理存储位置为L0B Buffer(TPosition: B2)。</td></tr><tr><td>src</td><td>输入</td><td>源操作数，类型为LocalTensor。<br>分形约束参考<a href="cube_compute_input_move_constraint.html">矩阵计算输入搬运约束</a>。<br>起始地址对齐约束参考<a href="cube_compute_input_move_constraint.html">对齐约束</a>。<br>支持的数据类型为int8_t。<br>Atlas A2 训练系列产品/Atlas A2 推理系列产品，支持的物理存储位置为L1 Buffer(TPosition: B1)。<br>Atlas A3 训练系列产品/Atlas A3 推理系列产品，支持的物理存储位置为L1 Buffer(TPosition: B1)。</td></tr><tr><td>idx</td><td>输入</td><td>源操作数，类型为LocalTensor。<br>数据分形大小为128字节，每个数据分形shape为16 * 32 * 2bit。<br>起始地址对齐约束参考<a href="cube_compute_input_move_constraint.html">对齐约束</a>。<br>支持的数据类型为uint8_t。<br>Atlas A2 训练系列产品/Atlas A2 推理系列产品，支持的物理存储位置为L1 Buffer(TPosition: B1)。<br>Atlas A3 训练系列产品/Atlas A3 推理系列产品，支持的物理存储位置为L1 Buffer(TPosition: B1)。</td></tr><tr><td>loadDataParam</td><td>输入</td><td>LoadData参数结构体，类型为：<br>  • LoadData2dParams，具体参考<a href="LoadData_2D.html#table_load2d_params">LoadData2dParams结构体内参数说明</a>。<br>需要注意的是，本接口仅支持连续的数据分形搬运，不支持跳stride，因此仅支持配置loadDataParam中的startIndex和repeatTimes参数，其余参数未使用，无需配置。</td></tr></tbody></table><h2 id="数据类型">数据类型<span id="zh-cn_topic_0000002512171654_section4219135304818"></span><a class="header-anchor" href="#数据类型">​</a></h2><p>支持数据类型为：src和dst支持int8_t，idx支持uint8_t。</p><h2 id="返回值说明">返回值说明<span id="zh-cn_topic_0000002512171654_section640mcpsimp"></span><a class="header-anchor" href="#返回值说明">​</a></h2><p>无</p><h2 id="约束说明">约束说明<span id="zh-cn_topic_0000002512171654_section2045914466492"></span><a class="header-anchor" href="#约束说明">​</a></h2><ul><li>当配置loadDataParam中参数repeatTimes=0时，表示不执行搬运，该接口将被视为NOP（空操作）。最大支持repeatTimes=255。</li><li>不支持转置功能，仅支持连续的数据分形搬运，不支持跳stride，仅支持配置loadDataParam中的startIndex和repeatTimes参数，其余参数未使用。</li><li>存放索引矩阵的专用buffer空间大小为L0B Buffer大小的四分之一，开发者无需配置地址，MmadWithSparse接口会自动从该buffer中读取数据。</li><li>仅支持L1 Buffer-&gt;L0B Buffer通路，且L1 Buffer上的分形为Zn。</li><li>每次迭代中的startIndex不能小于零。</li></ul><h2 id="调用示例">调用示例<span id="zh-cn_topic_0000002512171654_section088124295117"></span><a class="header-anchor" href="#调用示例">​</a></h2><p>本接口用于配合Sparse Mmad使用，完整示例请参考：<a href="https://gitcode.com/cann/asc-devkit/tree/master/examples/01_simd_cpp_api/03_basic_api/03_matrix_compute/mmad_with_sparse">MmadWithSparse调用样例</a>。</p></article></div>`,1)])])}const m=s(e,[["render",c]]);export{h as __pageData,m as default};
